/**
 * The SPARQL algebra defines {@code eval(Join(P1,P2)) = Join(eval(P1), eval(P2))}: the right operand denotes ONE
 * independently evaluated multiset. A nested-loop bind join re-evaluating a volatile right operand per left row would
 * observably deviate — each STRUUID() call must return a different value, so distinct values per row cannot arise from
 * any single evaluation of the operand. This algebra-level witness covers inner joins whose unsafe right operand is not
 * a scope change (not reachable from the parser, but reachable through programmatically constructed algebra, which is
 * public API).
 */
public class JoinIndependentOperandTest {

	@Test
	public void volatileInnerJoinRightOperandIsEvaluatedOnce() {
		SimpleValueFactory vf = SimpleValueFactory.getInstance();

		BindingSetAssignment values = new BindingSetAssignment();
		QueryBindingSet first = new QueryBindingSet();
		first.addBinding("x", vf.createLiteral(1));
		QueryBindingSet second = new QueryBindingSet();
		second.addBinding("x", vf.createLiteral(2));
		values.setBindingSets(List.of(first, second));

		Extension volatileRight = new Extension(new SingletonSet(),
				new ExtensionElem(new FunctionCall("STRUUID"), "u"));
		QueryRoot query = new QueryRoot(new Join(values, volatileRight));

		StrictEvaluationStrategy strategy = new StrictEvaluationStrategy(new EmptyTripleSource(), null);

		List<BindingSet> rows = new ArrayList<>();
		try (CloseableIteration<BindingSet> iteration = strategy.precompile(query)
				.evaluate(EmptyBindingSet.getInstance())) {
			while (iteration.hasNext()) {
				rows.add(iteration.next());
			}
		}

		assertEquals(2, rows.size());
		Set<Value> distinctU = new HashSet<>();
		for (BindingSet row : rows) {
			distinctU.add(row.getValue("u"));
		}
		assertEquals(1, distinctU.size(),
				"the join's right operand is evaluated independently once; its single fresh value joins with every left row");
	}

	/**
	 * An independently evaluated zero-length path enumerates graph subject/object nodes. Joining that relation with
	 * input rows yields matches only for those nodes; predicate-only and absent terms are not enumerated.
	 */
	@Test
	public void zeroLengthPathRightJoinOperandEnumeratesOnlyGraphNodes() throws Exception {
		SimpleValueFactory vf = SimpleValueFactory.getInstance();
		IRI subject = vf.createIRI("urn:subject");
		IRI predicateOnly = vf.createIRI("urn:predicate-only");
		IRI object = vf.createIRI("urn:object");
		IRI absent = vf.createIRI("urn:absent");
		ListTripleSource source = new ListTripleSource(vf,
				List.of(vf.createStatement(subject, predicateOnly, object)));

		BindingSetAssignment values = inputValues(subject, object, predicateOnly, absent);
		List<BindingSet> rows = evaluate(new Join(values, new ZeroLengthPath(Var.of("x"), Var.of("r"))), source);

		assertThat(rows).containsExactlyInAnyOrder(
				bindings("x", subject, "r", subject),
				bindings("x", object, "r", object));
		assertThat(rows.stream().map(BindingSet::getBindingNames).toList())
				.containsExactlyInAnyOrder(Set.of("x", "r"), Set.of("x", "r"));
	}

	/**
	 * OPTIONAL combines the independently enumerated graph-node relation with its input rows: matching subject/object
	 * terms get the zero-length result, while predicate-only and absent terms remain unchanged.
	 */
	@Test
	public void zeroLengthPathOptionalRightOperandLeavesNonNodesUnmatched() throws Exception {
		SimpleValueFactory vf = SimpleValueFactory.getInstance();
		IRI subject = vf.createIRI("urn:subject");
		IRI predicateOnly = vf.createIRI("urn:predicate-only");
		IRI object = vf.createIRI("urn:object");
		IRI absent = vf.createIRI("urn:absent");
		ListTripleSource source = new ListTripleSource(vf,
				List.of(vf.createStatement(subject, predicateOnly, object)));

		BindingSetAssignment values = inputValues(subject, object, predicateOnly, absent);
		List<BindingSet> rows = evaluate(new LeftJoin(values, new ZeroLengthPath(Var.of("x"), Var.of("r"))), source);

		assertThat(rows).containsExactlyInAnyOrder(
				bindings("x", subject, "r", subject),
				bindings("x", object, "r", object),
				binding("x", predicateOnly),
				binding("x", absent));
		assertThat(rows.stream().map(BindingSet::getBindingNames).toList())
				.containsExactlyInAnyOrder(Set.of("x", "r"), Set.of("x", "r"), Set.of("x"), Set.of("x"));
	}

	private static BindingSetAssignment inputValues(Value... values) {
		BindingSetAssignment assignment = new BindingSetAssignment();
		List<BindingSet> bindings = new ArrayList<>(values.length);
		for (Value value : values) {
			bindings.add(binding("x", value));
		}
		assignment.setBindingSets(bindings);
		return assignment;
	}

	private static QueryBindingSet binding(String name, Value value) {
		QueryBindingSet bindingSet = new QueryBindingSet();
		bindingSet.addBinding(name, value);
		return bindingSet;
	}

	private static QueryBindingSet bindings(String firstName, Value firstValue, String secondName, Value secondValue) {
		QueryBindingSet bindingSet = binding(firstName, firstValue);
		bindingSet.addBinding(secondName, secondValue);
		return bindingSet;
	}

	private static List<BindingSet> evaluate(TupleExpr expression, TripleSource source) throws Exception {
		StrictEvaluationStrategy strategy = new StrictEvaluationStrategy(source, null);
		List<BindingSet> rows = new ArrayList<>();
		try (CloseableIteration<BindingSet> iteration = strategy.precompile(new QueryRoot(expression))
				.evaluate(EmptyBindingSet.getInstance())) {
			while (iteration.hasNext()) {
				rows.add(iteration.next());
			}
		}
		return rows;
	}

	private record ListTripleSource(ValueFactory valueFactory, List<Statement> statements) implements TripleSource {
		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate, Value object,
				Resource... contexts) {
			return new CloseableIteratorIteration<>(statements.stream()
					.filter(statement -> subject == null || subject.equals(statement.getSubject()))
					.filter(statement -> predicate == null || predicate.equals(statement.getPredicate()))
					.filter(statement -> object == null || object.equals(statement.getObject()))
					.filter(statement -> contexts.length == 0 || List.of(contexts).contains(statement.getContext()))
					.iterator());
		}

		@Override
		public ValueFactory getValueFactory() {
			return valueFactory;
		}
	}
}
